// fal.ai Platform API Helper
// Shared utilities for all fal.ai models
// Auto-generated by scripts/falai-codegen — do not edit manually.

const FAL_API_BASE = "https://api.fal.ai/v1";

/**
 * Resolve the fal.ai API key: an explicit token (typically from the model's
 * vault-wireable apiToken global arg) takes precedence over the FAL_KEY
 * environment variable (fal.ai's standard SDK env var). Throws a descriptive
 * error when neither is set.
 */
function resolveToken(apiToken?: string): string {
  const token = apiToken ?? Deno.env.get("FAL_KEY");
  if (!token) {
    throw new Error(
      "fal.ai API key not set. Provide the apiToken global argument " +
        "(wireable with a vault.get(...) expression) or set the " +
        "FAL_KEY environment variable.",
    );
  }
  return token;
}

/**
 * fal.ai's documented error response shape: `{ error: { type, message, ... } }`.
 * Unlike Cloudflare's {success, result} envelope, every fal.ai response —
 * success or failure — is a bare JSON object; there is no top-level envelope
 * to unwrap on the success path.
 */
interface FalErrorBody {
  error?: { type?: string; message?: string };
}

/**
 * Sanitize a resource instance name for swamp's data layer.
 *
 * Swamp rejects data-artifact instance names containing "/", "\", "..", or
 * null bytes (path-traversal protection). Instance names are frequently derived
 * from API-returned identifiers, which are attacker-influenceable, so every
 * writeResource instance name is routed through this before it reaches the
 * datastore.
 */
export function sanitizeInstanceName(name: string): string {
  return name
    .replace(/[/\\]/g, "_")
    .replace(/\.\./g, "_")
    .replace(/\0/g, "");
}

/**
 * Deterministic short hash (SHA-1, first 16 hex chars) for building a
 * collision-resistant resource instance name when a create response carries
 * no id- or name-shaped field to key off of (e.g. `{ success: true }`,
 * `{ signed_url: "..." }`) — hashing the request instead of falling back to
 * a fixed "created" slot keeps distinct calls from overwriting each other.
 */
export async function shortHash(input: string): Promise<string> {
  const digest = await crypto.subtle.digest(
    "SHA-1",
    new TextEncoder().encode(input),
  );
  return Array.from(new Uint8Array(digest))
    .map((b) => b.toString(16).padStart(2, "0"))
    .join("")
    .slice(0, 16);
}

const MAX_RETRIES = 3;

/** Hard deadline for a single HTTP attempt, including draining the body. */
const REQUEST_TIMEOUT_MS = 60_000;

/** Upper bound on any single 429 back-off, however large Retry-After is. */
const MAX_RETRY_DELAY_MS = 30_000;

/**
 * Result of a fetch, with the body already drained to text exactly once —
 * Response.text()/.json() can only be called once per response, so every
 * caller reads FalFetchResult.body instead of touching response.text() again.
 */
interface FalFetchResult {
  response: Response;
  body: string;
}

/**
 * One HTTP attempt under a hard deadline. The abort signal covers both the
 * request and the body drain, so a server that sends headers and then stalls
 * cannot hang the caller. A timeout surfaces as a descriptive error naming the
 * method, URL and deadline rather than a bare DOMException.
 */
async function fetchWithTimeout(
  url: string,
  init: RequestInit,
): Promise<FalFetchResult> {
  const method = init.method ?? "GET";
  try {
    const response = await fetch(url, {
      ...init,
      signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
    });
    return { response, body: await response.text() };
  } catch (err) {
    if (err instanceof DOMException && err.name === "TimeoutError") {
      throw new Error(
        `fal.ai API request timed out after ${
          REQUEST_TIMEOUT_MS / 1000
        }s: ${method} ${url}`,
      );
    }
    throw err;
  }
}

/**
 * Perform a fetch with bounded retry on HTTP 429. Honors the `Retry-After`
 * header when present (seconds, capped at MAX_RETRY_DELAY_MS), otherwise backs
 * off linearly. Every attempt has its own timeout. Returns the final response
 * with its body pre-drained to text; does not throw on non-429 statuses.
 */
async function falFetch(
  url: string,
  init: RequestInit,
): Promise<FalFetchResult> {
  for (let attempt = 0; attempt <= MAX_RETRIES; attempt++) {
    const result = await fetchWithTimeout(url, init);
    if (result.response.status !== 429) return result;
    if (attempt === MAX_RETRIES) return result;

    const retryAfter = result.response.headers.get("Retry-After");
    const parsed = retryAfter ? Number(retryAfter) : NaN;
    const delayMs = Math.min(
      Number.isFinite(parsed) && parsed >= 0
        ? parsed * 1000
        : 1000 * (attempt + 1),
      MAX_RETRY_DELAY_MS,
    );
    await new Promise((r) => setTimeout(r, delayMs));
  }
  // Unreachable: the loop returns on the final attempt.
  throw new Error(`fal.ai API request failed: ${url}`);
}

/**
 * Parse a successful response body as JSON. An empty or whitespace-only body
 * (a 200/202/204 with no content) is "no content" and yields undefined; a
 * malformed body throws an error carrying the method, path and status instead
 * of a bare SyntaxError with no context.
 */
function parseJsonBody<T>(
  body: string,
  method: string,
  path: string,
  status: number,
): T | undefined {
  if (body.trim() === "") return undefined;
  try {
    return JSON.parse(body) as T;
  } catch (err) {
    throw new Error(
      `fal.ai API returned malformed JSON: ${method} ${path} (status ${status}): ${
        (err as Error).message
      }; body starts: ${body.slice(0, 200)}`,
    );
  }
}

/** Extract a human-readable error message from a fal.ai error response body. */
function extractErrorMessage(body: string): string {
  try {
    const parsed = JSON.parse(body) as FalErrorBody;
    if (parsed.error?.message) {
      return parsed.error.message;
    }
  } catch {
    // Not JSON — fall through to the raw text.
  }
  return body.slice(0, 500);
}

export async function falApi<T>(
  apiToken: string,
  method: string,
  path: string,
  body?: unknown,
): Promise<T> {
  const token = resolveToken(apiToken);
  const url = `${FAL_API_BASE}${path}`;
  const headers: Record<string, string> = {
    "Authorization": `Key ${token}`,
    "Content-Type": "application/json",
  };

  const { response, body: responseBody } = await falFetch(url, {
    method,
    headers,
    body: body !== undefined ? JSON.stringify(body) : undefined,
  });

  if (response.status === 429) {
    throw new Error(
      `fal.ai API rate limited after ${MAX_RETRIES} retries: ${method} ${path}`,
    );
  }

  if (!response.ok) {
    const message = extractErrorMessage(responseBody);
    throw new Error(
      `fal.ai API error: ${method} ${path} returned ${response.status} ${response.statusText}: ${message}`,
    );
  }

  return parseJsonBody<T>(responseBody, method, path, response.status) as T;
}

/**
 * Like falApi, for endpoints whose response body IS the data the caller
 * stores. An empty 2xx body there is a gateway or server fault, not "no
 * content", so it raises a clear error instead of returning undefined for the
 * caller to trip over.
 */
export async function falApiData<T>(
  apiToken: string,
  method: string,
  path: string,
  body?: unknown,
): Promise<T> {
  const result = await falApi<T>(apiToken, method, path, body);
  if (result === undefined || result === null) {
    throw new Error(
      `fal.ai API returned an empty response body: ${method} ${path}`,
    );
  }
  return result;
}

const MAX_PAGES = 20;

export interface PaginatedResult<T> {
  results: T[];
  truncated: boolean;
  totalFetched: number;
}

export interface PaginationOptions {
  /** Caller-requested result cap. Stops fetching once reached; results are
   * sliced to exactly this many. Omit to fetch every page up to MAX_PAGES. */
  limit?: number;
  /** Caller-supplied cursor to resume from, rather than starting at page 1. */
  cursor?: string;
}

/**
 * Fetch every page of a cursor-paginated fal.ai list endpoint.
 *
 * fal.ai responses are bare JSON objects with a per-endpoint list field name
 * (`resultsField`, e.g. "assets", "instances") rather than a fixed envelope
 * key — the caller supplies it, detected at codegen time by pagination.ts.
 * When the response carries `next_cursor`/`has_more`, those drive the stop
 * condition; otherwise pagination stops once a page is shorter than the
 * requested limit, matching cloudflare-codegen's fallback heuristic.
 *
 * `options.limit`/`options.cursor` are the *caller's* pagination args (the
 * method's own `limit`/`cursor` schema fields) — distinct from the internal
 * per-request page size below, which is always 100 regardless of what the
 * caller asked for.
 */
export async function falApiPaginated<T>(
  apiToken: string,
  path: string,
  resultsField: string,
  params?: Record<string, string | string[]>,
  options?: PaginationOptions,
): Promise<PaginatedResult<T>> {
  const token = resolveToken(apiToken);
  const allResults: T[] = [];
  const pageSize = 100;
  const targetLimit = options?.limit;
  let cursor: string | undefined = options?.cursor;
  let truncated = false;

  for (let page = 1; page <= MAX_PAGES; page++) {
    const queryParams = new URLSearchParams();
    for (const [k, v] of Object.entries(params ?? {})) {
      if (Array.isArray(v)) {
        for (const item of v) queryParams.append(k, item);
      } else {
        queryParams.append(k, v);
      }
    }
    queryParams.set("limit", String(pageSize));
    if (cursor) queryParams.set("cursor", cursor);

    const url = `${FAL_API_BASE}${path}?${queryParams}`;
    const { response, body: responseBody } = await falFetch(url, {
      headers: {
        "Authorization": `Key ${token}`,
      },
    });

    if (response.status === 429) {
      throw new Error(
        `fal.ai API rate limited after ${MAX_RETRIES} retries: GET ${path}`,
      );
    }

    if (!response.ok) {
      const message = extractErrorMessage(responseBody);
      throw new Error(
        `fal.ai API error: GET ${path} returned ${response.status} ${response.statusText}: ${message}`,
      );
    }

    // An empty 2xx body is an empty page, not an error.
    const data = parseJsonBody<Record<string, unknown>>(
      responseBody,
      "GET",
      path,
      response.status,
    ) ?? {};
    const items = (data[resultsField] as T[] | undefined) ?? [];
    allResults.push(...items);

    const hasMore = typeof data.has_more === "boolean"
      ? data.has_more
      : undefined;
    const nextCursor = typeof data.next_cursor === "string"
      ? data.next_cursor
      : undefined;

    if (targetLimit !== undefined && allResults.length >= targetLimit) {
      // Reached the caller's requested count. More data may still exist
      // beyond it — truncated reflects that possibility, not an error.
      truncated = allResults.length > targetLimit ||
        hasMore === true ||
        (hasMore === undefined && items.length >= pageSize);
      break;
    }

    if (hasMore !== undefined) {
      if (!hasMore) break;
      if (!nextCursor) {
        // has_more is true but the API gave us no cursor to continue with —
        // more data exists that this call cannot reach.
        truncated = true;
        break;
      }
      cursor = nextCursor;
    } else {
      // No has_more/next_cursor in the response: fall back to the
      // shorter-than-requested-page heuristic.
      if (items.length < pageSize) break;
      if (page >= MAX_PAGES) {
        truncated = true;
        break;
      }
      // Without an explicit cursor, further pagination cannot proceed. A
      // full page with nothing to continue with means more data may exist
      // that this call cannot reach.
      if (!nextCursor) {
        truncated = true;
        break;
      }
      cursor = nextCursor;
    }

    if (page >= MAX_PAGES) {
      truncated = true;
    }
  }

  const results = targetLimit !== undefined
    ? allResults.slice(0, targetLimit)
    : allResults;
  return { results, truncated, totalFetched: allResults.length };
}
